DECLARE @sql nvarchar(max) = N'';
SELECT @sql += N'ALTER TABLE [customer] DROP CONSTRAINT ' + QUOTENAME(d.name) + N';' FROM sys.default_constraints d
    WHERE d.parent_object_id = OBJECT_ID(N'[customer]') AND d.parent_column_id = COLUMNPROPERTY(OBJECT_ID(N'[customer]'), N'since', 'ColumnId');
EXEC sp_executesql @sql;

